={{ JSON.stringify({
  model: $env['AI_MODEL_VISION_' + $env.AI_PROVIDER],
  max_tokens: 3000,
  temperature: 0.1,
  messages: [
    {
      role: "system",
      content: "You are an expert product identification specialist with encyclopedic knowledge of consumer electronics, appliances, collectibles, toys, tools, clothing, furniture, sporting goods, musical instruments, and all major resale categories. Your sole purpose is to precisely identify items from photos so they can be listed on eBay and Facebook Marketplace. Accuracy is paramount — if you are unsure, say so and give your best assessment. Always respond in raw, valid JSON only. No markdown, no prose, no code fences. For licensed collectibles and branded merchandise (game art, movie memorabilia, sports collectibles, convention exclusives, etc.), be especially careful not to invent a plausible-sounding but unofficial title — the same artwork is often sold as both an official product AND unrelated fan-made/print-on-demand reproductions under different names. If you recognize the subject matter or brand but are not certain of the exact commercial product name, describe what you see accurately and set confidence to \"medium\" or \"low\" rather than presenting a guessed name with high confidence."
    },
    {
      role: "user",
      content: [
        {
          type: "image_url",
          image_url: {
            url: $('Set Variables').item.json.photo_url
          }
        },
        {
          type: "text",
          text: `Analyze this image and identify the product as precisely as possible.

Seller-provided context: If the seller's name for the item looks like a specific, real product title (not a vague description like \"old radio\" or \"game thing\"), treat it as a strong and likely-accurate signal — sellers often know exactly what they own, especially for collectibles and licensed merchandise, and this is frequently more reliable than a name inferred purely from the image. Use your visual analysis to CONFIRM it matches (color, shape, artwork, packaging) rather than to invent a different name. Only override a specific seller-provided name if the visual evidence clearly contradicts it. If the seller's name is vague, missing, or clearly wrong, fall back to your own visual analysis.
- Seller's name for item: ${$('Set Variables').item.json.seller_name || 'Not provided'}
- Condition stated by seller: ${$('Set Variables').item.json.seller_condition}
- Missing items noted: ${$('Set Variables').item.json.missing_items}
- Seller notes: ${$('Set Variables').item.json.seller_notes || 'None'}

Return ONLY this exact JSON structure — no extra fields, no wrapping:
{
  "identified_product_name": "Full descriptive product name — use the seller-provided name verbatim (or lightly cleaned up) if it looked specific and you confirmed it visually matches; otherwise your own best description (e.g. Sony PlayStation 4 Pro 1TB Gaming Console)",
  "brand": "Brand name or Unknown",
  "model": "Model name (e.g. PS4 Pro) or Unknown",
  "model_number": "Specific model/part number if visible (e.g. CUH-7215B) or Unknown",
  "category": "Primary resale category (Electronics | Toys & Games | Clothing | Tools | Furniture | Collectibles | Sports | Music | Other)",
  "subcategory": "More specific subcategory (e.g. Gaming Console, Action Figure, Power Tool)",
  "color": "Primary color(s) of this item",
  "visible_condition_notes": "What you can objectively observe about condition from the image (scratches, wear, damage, cleanliness)",
  "identifying_features": ["list of key visual features that confirm identification"],
  "approximate_era": "Decade or year range if determinable (e.g. 1990s, 2015-2018) or null",
  "search_query_primary": "Best web search query to find this exact product. If the seller provided a specific product name, use that as the basis for this query first. Otherwise use brand + model/number (3-6 words); if confidence is not \"high\", base it on the visual subject matter and brand rather than an invented title (e.g. \"Diablo IV Lilith Inarius art print Blizzard\" instead of a made-up title you are not sure of).",
  "search_query_alt": "Alternative query if primary is too specific or if brand is unknown",
  "search_query_ebay": "Search query optimized for finding this on eBay sold listings",
  "confidence": "high | medium | low",
  "confidence_reason": "One sentence explaining your confidence level"
}`
        }
      ]
    }
  ]
}) }}

parameters.jsCode:
const raw = $input.item.json.choices[0].message.content;
let cleaned = raw.replace(/```json|```/g, '').trim();
const braceStart = cleaned.indexOf('{');
const braceEnd = cleaned.lastIndexOf('}');
if (braceStart !== -1 && braceEnd !== -1 && braceEnd > braceStart) {
  cleaned = cleaned.slice(braceStart, braceEnd + 1);
}
try {
  return { json: JSON.parse(cleaned) };
} catch(e) {
  return { json: {
    identified_product_name: "Unknown Product",
    brand: "Unknown", model: "Unknown", model_number: "Unknown",
    category: "Other", subcategory: "Unknown",
    color: "Unknown", visible_condition_notes: "Unable to parse AI response",
    identifying_features: [], search_query_primary: "item for sale",
    search_query_alt: "used item", search_query_ebay: "used item",
    confidence: "low", confidence_reason: "AI response parse failed: " + e.message
  }};
}

parameters.jsonBody:
={{ JSON.stringify({
  model: $env['AI_MODEL_RESEARCH_' + $env.AI_PROVIDER],
  max_tokens: 4000,
  temperature: 0.2,
  messages: [
    {
      role: "system",
      content: "You are a professional product researcher specializing in the secondhand and resale market. You create comprehensive, accurate product profiles from image analysis and web search results. Your profiles are used directly to create eBay and Facebook Marketplace listings — accuracy and completeness are critical. Always respond in raw, valid JSON only. No markdown, no prose, no code fences."
    },
    {
      role: "user",
      content: `Synthesize the following data into a comprehensive product profile.

IMAGE ANALYSIS RESULT:
${JSON.stringify($('Parse Image Recognition').item.json)}

SELLER INFO:
- Seller's name for item: ${$('Set Variables').item.json.seller_name || 'Not provided'}
- Condition: ${$('Set Variables').item.json.seller_condition}
- Missing items: ${$('Set Variables').item.json.missing_items}
- Notes: ${$('Set Variables').item.json.seller_notes || 'None'}

WEB SEARCH RESULTS — Product Identification:
${$('Brave Search 1: Product Identification').item.json.web?.results?.slice(0,5).map(r => '• ' + r.title + '\n  ' + r.description).join('\n\n') ?? 'No results'}

WEB SEARCH RESULTS — Specifications:
${$('Brave Search 2: Specifications').item.json.web?.results?.slice(0,5).map(r => '• ' + r.title + '\n  ' + r.description).join('\n\n') ?? 'No results'}

WEB SEARCH RESULTS — Retail Price:
${$('Brave Search 3: Retail Price').item.json.web?.results?.slice(0,5).map(r => '• ' + r.title + '\n  ' + r.description).join('\n\n') ?? 'No results'}

IMPORTANT — VERIFY BEFORE CONFIRMING:
- Check whether the web search results actually support the image analysis's guessed name. If most \"Product Identification\" results point to third-party/fan-made/print-on-demand sources (Etsy, INPRNT, Redbubble, DeviantArt, Society6, etc.) rather than the official brand, publisher, or an authorized retailer, treat the guessed name as UNVERIFIED — look through the results for a more official product name and use that instead if you find one.
- If multiple similarly-themed products appear (different editions, sizes, or formats of related merchandise — e.g. canvas vs. framed print, numbered/limited vs. mass-market), identify which SPECIFIC one matches this item's physical description rather than defaulting to whichever has the most search results.
- Only use a retail price if its source clearly refers to the SAME confirmed product, edition, and format — never substitute the price of a similar-but-different or currently-sold item for one that may be discontinued.
- If this item appears to be discontinued, a convention/event exclusive, or a limited/numbered edition, say so explicitly in short_description and key_features — this materially affects resale value.

Return ONLY this exact JSON:
{
  "confirmed_product_name": "Full verified product name",
  "brand": "Brand name",
  "model": "Model name",
  "model_number": "Model/part number or null",
  "upc": "UPC if found or null",
  "asin": "Amazon ASIN if found or null",
  "category": "Primary category",
  "subcategory": "Subcategory",
  "year_released": "Year or year range or null",
  "country_of_origin": "Country or null",
  "item_color": "The specific color of this particular item",
  "colors_available": ["all colors this model came in"],
  "dimensions": {
    "length": "value or null",
    "width": "value or null",
    "height": "value or null",
    "weight": "value or null",
    "unit": "inches/lbs or cm/kg"
  },
  "key_features": ["feature 1", "feature 2", "up to 10 key features"],
  "materials": ["primary materials"],
  "whats_in_box_new": ["what comes in box when purchased new"],
  "whats_included_this_item": ["what appears to be included with this specific item based on seller notes and condition"],
  "condition_full_description": "Detailed, honest condition description incorporating seller_condition level, missing_items, visible_condition_notes, and seller_notes. Written in professional listing language.",
  "ebay_item_specifics": {
    "Brand": "",
    "Model": "",
    "MPN": "or Does Not Apply",
    "Type": "",
    "Color": "",
    "Unit Type": "or N/A",
    "Country/Region of Manufacture": "or Unknown"
  },
  "short_description": "2-3 sentence product description for listings",
  "retail_price_usd": "number or null — original MSRP from research",
  "current_new_price_usd": "number or null — what it costs new today",
  "comparable_search_query": "A SHORT, broad search query (4-7 words) for finding market comparables — brand + core subject/theme only, deliberately omitting exact dimensions, edition wording, or full formal title. For niche/rare items where an exact-title match will not exist, this should be broad enough to surface visually or thematically SIMILAR items (same franchise, brand line, art style, or collectible category), not just identical ones. E.g. \"Blizzard Diablo IV collectible art print\" rather than \"Diablo Birth of the Nephalem Framed 12.75 x 30 Art Print\"."
}`
    }
  ]
}) }}

