// Buffer.from() inside a {{ }} expression silently evaluates to an empty
// string in n8n's expression sandbox (it is not full Node.js) -- that was
// producing 'Basic ' with nothing after it, hence every eBay OAuth call
// failing with invalid_client. Computing it here in a Code node (real
// Node.js) and referencing the plain string downstream fixes it.
return { json: { ebay_auth_header: 'Basic ' + Buffer.from($env.EBAY_CLIENT_ID + ':' + $env.EBAY_CLIENT_SECRET).toString('base64') } };
